    pub optional: bool,
}

/// One per-occurrence node in the dependencies tree. Mirrors upstream's
/// [`DependenciesTreeNode`](https://github.com/pnpm/pnpm/blob/097983fbca/installing/deps-resolver/src/resolveDependencies.ts#L92-L103).
